insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 2, '2.1', array['2.1']::text[], 'convention', 'Electronegativity trends in the periodic table', 'Electronegativity of the representative elements increases from left to right across a period and decreases going down a group, which can be explained qualitatively with electronic structure, the shell model, and Coulomb''s law.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u2-r2-001; ced=2.1.A.1: "Electronegativity values for the representative elements increase going from left to right across a period and decrease going down a group."')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
