insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 2, '2.2', array['2.2', '2.3']::text[], 'convention', 'Coulomb''s law and cation–anion interaction strength', 'Larger ion charges give stronger interactions, and smaller ions (shorter distance between the ion centers) give stronger interactions.', '[{"label": "Larger charges", "meaning": "Interaction strength is proportional to the charge on each ion, so stronger."}, {"label": "Smaller ions", "meaning": "Interaction strength increases as the distance between nuclei decreases, so stronger."}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u2-r1-009; ced=2.2.A.3.i–ii "larger charges lead to stronger interactions"; "smaller ions lead to stronger interactions"')
