values ('ap_chemistry', 2, '2.3', array['2.3']::text[], 'convention', 'Particulate model of an ionic solid', 'Cations and anions sit in a systematic, periodic 3-D array that maximizes attractive forces and minimizes repulsive forces among the ions.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u2-r1-010; ced=2.3.A.1 "systematic, periodic 3-D array that maximizes the attractive forces among cations and anions while minimizing the repulsive forces"')
