values ('ap_chemistry', 2, '2.4', array['2.4']::text[], 'vocabulary', 'Substitutional alloy', 'A substitutional alloy forms between atoms of comparable radius, with one atom substituting for the other in the lattice (e.g., zinc substituting for copper in certain brasses).', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u2-r1-013; ced=2.4.A.3 "atoms of comparable radius, where one atom substitutes for the other in the lattice"')
