insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 2, '2.6', array['2.6']::text[], 'convention', 'Limitation of the Lewis model', 'The Lewis structure model has limitations, particularly for species with an odd number of valence electrons.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u2-r1-017; ced=2.6.A.3 "particularly in cases with an odd number of valence electrons"')
