insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 2, '2.7', array['2.7']::text[], 'list_sequence', 'Hybridization and ideal bond angles', 'The sp, sp2, and sp3 hybridization labels for a central atom correspond to ideal bond angles of 180°, 120°, and 109.5°.', '[{"label": "sp", "meaning": "Ideal bond angles of 180°"}, {"label": "sp2", "meaning": "Ideal bond angles of 120°"}, {"label": "sp3", "meaning": "Ideal bond angles of 109.5°"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u2-r2-006; ced=2.7.A.3: "sp hybridized, its ideal bond angles are 180°; for sp2 hybridized atoms the bond angles are 120°; and for sp3 hybridized atoms the bond angles are 109.5°."')
