insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 2, '2.7', array['2.7']::text[], 'list_sequence', 'Molecular geometries named in the CED', 'The molecular geometries that students must predict from Lewis diagrams and VSEPR theory, in the CED''s order.', '[{"label": "Linear", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "Trigonal planar", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "Tetrahedral", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "Trigonal pyramidal", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "Bent", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "Trigonal bipyramidal", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "Seesaw", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "T-shaped", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "Octahedral", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "Square pyramidal", "meaning": "Molecular geometry named in 2.7.A.2.i"}, {"label": "Square planar", "meaning": "Molecular geometry named in 2.7.A.2.i"}]'::jsonb, NULL, 'Answer with the geometry name itself. A bond angle alone, or an invalid combined label such as ''tetrahedral pyramidal'', does not earn the point. For more than four electron pairs around the central atom, only the shape of the molecule is required.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u2-r2-007; ced=2.7.A.2.i: "Molecular geometry (linear, trigonal planar, tetrahedral, trigonal pyramidal, bent, trigonal bipyramidal, seesaw, T-shaped, octahedral, square pyramidal, square planar)"')
