insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 2, '2.7', array['2.7']::text[], 'convention', 'Sigma and pi bonds', 'Bond formation involves orbital overlap, and multiple bonds contain both sigma and pi bonds; sigma overlap is stronger, so sigma bonds have greater bond energy than pi bonds, and a pi bond prevents rotation about the bond and leads to geometric isomers.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u2-r1-021; ced=2.7.A.4 "sigma bonds having greater bond energy than pi bonds. The presence of a pi bond also prevents the rotation of the bond and leads to geometric isomers"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_chemistry', 2, '2.7', array['2.7']::text[], 'vocabulary', 'VSEPR theory', 'VSEPR theory uses the Coulombic repulsion between electrons to predict the arrangement of electron pairs around a central atom.', '[]'::jsonb, NULL, 'VSEPR must be used together with the Lewis diagram to predict molecular geometry, bond angles, and dipole moment.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-chemistry-reference-u2-u3-2026-10-10; candidate=ap_chemistry-u2-r1-018; ced=2.7.A.1 "Coulombic repulsion between electrons as a basis for predicting the arrangement of electron pairs"')
